<template><ops-shell title="Operations incidents" description="Health checks create deduplicated incidents. Assign an owner, document handling, verify recovery and then close; recurring failures reopen the incident." :tabs="tabs"><section class="ops-card"><ops-fields :record="{status:health.status,fresh:health.fresh,sample_at:health.generated_at}"/><button @click="sync" :disabled="busy">{{ $t('Refresh health incidents') }}</button><p class="ops-muted">{{ $t('The scheduler imports health results every minute. Refresh only records operational events and does not retry transfers.') }}</p></section>
<form class="ops-card ops-form" @submit.prevent="search"><label>{{ $t('Status') }}<themed-select v-model="query.status"><option value="">{{ $t('All') }}</option><option v-for="s in ['open','acknowledged','investigating','resolved']" :key="s" :value="s">{{ $t(s) }}</option></themed-select></label><label>{{ $t('Responsible operator ID') }}<themed-select v-model="query.assigned_to"><option value="">{{ $t('All') }}</option><option v-for="op in operators" :key="op.id" :value="op.id">#{{ op.id }} · {{ op.name }}</option></themed-select></label><label>{{ $t('Due status') }}<themed-select v-model="query.overdue"><option value="">{{ $t('All') }}</option><option value="1">{{ $t('Overdue') }}</option></themed-select></label><div class="ops-actions"><button type="submit">{{ $t('Filter') }}</button></div></form>
<p v-if="!incidents.data.length">{{ $t('No recorded incidents. Check monitoring freshness before concluding services are healthy.') }}</p><section v-for="r in incidents.data" :key="r.id" class="ops-card"><h2>#{{ r.id }} · {{ $t(r.guide[0]) }}</h2><p>{{ $t(r.guide[1]) }}</p><ops-fields :record="{status:r.status,severity:r.severity,assigned_to:r.assigned_to,due_at:r.due_at,opened_at:r.opened_at,recovery_at:r.recovery_at,resolved_at:r.resolved_at}"/><h3>{{ $t('Current evidence') }}</h3><ops-fields :record="r.current"/><h3>{{ $t('Suggested procedure') }}</h3><p>{{ $t(r.guide[2]) }}</p><div class="ops-links"><Link :href="route('admin.operations.incident',{id:r.id})">{{ $t('Processing history') }} ↗</Link></div><details><summary>{{ $t('Handle incident') }}</summary><case-form :record="r" :incident="true" :can-resolve="r.can_resolve" :operators="operators" :url="route('admin.operations.incident.update',{id:r.id})"/></details></section><pagination :links="incidents.links"/></ops-shell></template>
<script>
import OpsShell from './Shell';import OpsFields from './Fields';import CaseForm from './CaseForm';import Pagination from '@/Jetstream/Pagination';
export default {components:{OpsShell,OpsFields,CaseForm,Pagination},props:{tabs:Array,incidents:Object,health:Object,operators:Array,filters:Object},data(){return {busy:false,query:{status:this.filters.status||'',assigned_to:this.filters.assigned_to||'',overdue:this.filters.overdue||''}}},methods:{search(){this.$inertia.get(this.route('admin.operations.incidents'),Object.fromEntries(Object.entries(this.query).filter(([k,v])=>v!=='')))},sync(){this.$inertia.post(this.route('admin.operations.incidents.sync'),{},{preserveScroll:true,onStart:()=>this.busy=true,onFinish:()=>this.busy=false})}}};
</script>
